def per_hour(total_per_hour, mix):
    if abs(sum(mix.values()) - 100) > 1e-9:
        raise ValueError('mix must sum to 100')
    rate = total_per_hour / 3600
    return {k: round(rate * p / 100, 3) for k, p in mix.items()}

