coding.solution:
def pacing_sleep(pace_ms, iteration_elapsed_ms):
    return max(0, pace_ms - iteration_elapsed_ms)

def achieved_rate(pace_ms, elapsed_list):
    total = sum(max(pace_ms, e) for e in elapsed_list)
    return round(len(elapsed_list) * 60000 / total, 2)
